import collections

def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    def valley(n, hi, distinct):
        if distinct:
            vals = sorted(rng.sample(range(1, hi + 1), n))
        else:
            vals = sorted(rng.randint(1, hi) for _ in range(n))
        d = collections.deque([vals[-1]])
        for v in reversed(vals[:-1]):
            if rng.random() < 0.5:
                d.appendleft(v)
            else:
                d.append(v)
        return list(d)

    tests = [fmt([1]), fmt([5, 5]), fmt([1, 2, 3, 4]), fmt([4, 3, 2, 1]), fmt([2, 2, 2, 2, 2]),
             fmt([1, 3, 4, 5, 6, 3, 2]), fmt([2, 3, 4, 9, 1, 8, 2]), fmt([3, 1, 4, 2, 3]),
             fmt([1, 5, 1]), fmt([1, 2, 1, 2]), fmt([10**9, 1]), fmt([7, 7, 7, 7, 7])]
    for n in range(2, 13):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 6) for _ in range(n)]))
        tests.append(fmt([rng.randint(1, 30) for _ in range(n)]))
        tests.append(fmt(valley(n, 40, False)))
    for n in (5, 9, 14, 20, 30):
        tests.append(fmt(valley(n, 10**9, True)))
    tests.append(fmt([1] + list(range(2, 50001)) + [1]))
    tests.append(fmt(valley(100000, 10**9, True)))
    tests.append(fmt(valley(100000, 100000, False)))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt(list(range(1, 100001))))
    tests.append(fmt(list(range(100000, 0, -1))))
    tests.append(fmt([42] * 100000))
    return tests
